BEGIN
  DECLARE added ARRAY<STRING>;
  DECLARE add_columns STRING;

  SET added = [];
  -- the append creates production with every listed column
  IF EXISTS (
    SELECT 1 FROM `test-project.mock_da2_scan_prod.INFORMATION_SCHEMA.TABLES`
    WHERE table_name = prod_table_name
  ) THEN
    SET added = ARRAY(
      SELECT column_name FROM `test-project.mock_da2_scan_staging.INFORMATION_SCHEMA.COLUMNS`
      WHERE table_name = staging_table_name
        AND column_name IN UNNEST(columns)
        AND column_name NOT IN (
          SELECT column_name FROM `test-project.mock_da2_scan_prod.INFORMATION_SCHEMA.COLUMNS`
          WHERE table_name = prod_table_name
        )
      ORDER BY ordinal_position
    );
    SET add_columns = (
      SELECT STRING_AGG(
        FORMAT('ADD COLUMN IF NOT EXISTS `%s` %s', column_name, data_type),
        ', ' ORDER BY ordinal_position)
      FROM `test-project.mock_da2_scan_staging.INFORMATION_SCHEMA.COLUMNS`
      WHERE table_name = staging_table_name
        AND column_name IN UNNEST(added)
    );
    IF add_columns IS NOT NULL THEN
      EXECUTE IMMEDIATE FORMAT(
        'ALTER TABLE `%s.%s.%s` %s',
        'test-project', 'mock_da2_scan_prod', prod_table_name, add_columns);
    END IF;
  END IF;
END
